import numpy as np, json, os

# Summary of findings:
# r2 (base run): L2H0 pattern = perfect swap-partner routing (1.000 at swap partner)
#                L0H0 pattern = mostly self-attention, token-dependent, non-binary write
# r6 (ablate L0H0): NO effect on predictions → L0H0 is non-critical MAPPER
# r7 (ablate L2H0): Complete prediction failure → L2H0 is critical ROUTER
# r8 (ablate L0_MLP): Partial degradation (later positions fail) → critical MAPPER
# r9 (ablate L1_MLP): Severe degradation (most positions wrong) → critical MAPPER

submission = {
    "tags": {
        "L0H0_ATTN": "MAPPER",
        "L0_MLP": "MAPPER",
        "L1_MLP": "MAPPER",
        "L2H0_ATTN": "ROUTER"
    },
    "evidence": {
        "L0H0_ATTN": {
            "hypothesis": "Head 0 of layer 0 mostly self-attends in a token-dependent way and writes a non-binary 24-d vector at each position; ablating it leaves all predictions unchanged, confirming it is a per-position token-representation mapper (not a router or cross-position aggregator).",
            "test": "r6",
            "supports": True
        },
        "L0_MLP": {
            "hypothesis": "Layer 0 MLP transforms the per-position residual (write norm ~8-14, sensitive primarily to own token value: diff 8.8 vs 0.79 for neighbor) into richer representations; ablation causes partial prediction failures, confirming an independent per-position mapping role.",
            "test": "r8",
            "supports": True
        },
        "L1_MLP": {
            "hypothesis": "Layer 1 MLP applies the largest per-position transformation (write norm ~27-48, primarily own-token sensitive: diff 17.9 vs 2.3 for neighbor); ablation severely breaks predictions at most positions, confirming it is the dominant per-position mapper building the token representations that L2H0 reads.",
            "test": "r9",
            "supports": True
        },
        "L2H0_ATTN": {
            "hypothesis": "Head 0 of layer 2 attends to the swap-partner position with probability 1.000 at every position (pos1→pos2, pos2→pos1, …, pos9→pos9) based purely on positional index; ablation completely destroys predictions, confirming it is the sole routing component that moves the swap-partner's representation to each output position.",
            "test": "r7",
            "supports": True
        }
    }
}

os.makedirs('/work', exist_ok=True)
with open('/work/submission.json', 'w') as f:
    json.dump(submission, f, indent=2)
print("Saved /work/submission.json")
print(json.dumps(submission, indent=2))

